pa<-do.call(rbind,pars);wc(pa,'US_adaptation_parameters');saveRDS(pa,'frozen_US_adaptation.rds');ah<-unname(tools::md5sum('frozen_US_adaptation.rds'))
cutpoints<-read.csv(file.path(base,'US_BCT_recalibration_ladder_20260910','heldout_height_cutpoints.csv'));out<-list();raw<-list();age<-list();height<-list();scores<-list()
for(s in c('Female','Male'))for(fam in c('NO','BCCG','BCT')){
 d<-subset(us,eligible&cycle=='H'&sex==s);a<-subset(pa,sex==s&family==fam);p<-score_model(models[[paste(s,fam,sep='_')]],d);stopifnot(!any(p$clipped));z<-(p$z-a$center)/a$scale;m<-profile(d,z,subset(cutpoints,sex==s)$height);meta<-data.frame(sex=s,family=fam,N=nrow(d));key<-paste(s,fam)
 out[[key]]<-cbind(meta,m$profile);raw[[key]]<-cbind(meta,m$summary);age[[key]]<-cbind(meta,m$age);height[[key]]<-cbind(meta,m$height);scores[[key]]<-data.frame(SEQN=d$SEQN,sex=s,family=fam,z=z)
 if(fam=='BCT'){old<-readRDS(file.path(base,'US_BCT_recalibration_ladder_20260910','heldout_scores.rds'));old<-subset(old,sex==s&method=='Location_scale');stopifnot(max(abs(z-old$z[match(d$SEQN,old$SEQN)]))<1e-12)}
}
