stopifnot(hash==unname(tools::md5sum('frozen_pooled_family_models.rds')),ah==unname(tools::md5sum('frozen_US_adaptation.rds')),nrow(ss)==6,sum(ss$N[ss$family=='BCT'])==4898)
kr<-read.csv('Korea_OOF_nine_metrics.csv');both<-rbind(cbind(setting='Korea OOF',kr),cbind(setting='US held-out',ss[,names(kr)]));wc(both,'family_performance_profile')
met<-names(kr)[-(1:2)];l<-do.call(rbind,lapply(met,function(nm)data.frame(both[,c('setting','sex','family')],metric=nm,value=both[[nm]])));l$metric<-factor(l$metric,levels=met);mx<-tapply(l$value,l$metric,max);l$intensity<-l$value/as.numeric(mx[as.character(l$metric)]);l$label<-ifelse(l$metric %in% met[1:4],sprintf('%.3f',l$value),sprintf('%.2f',l$value));l$row<-paste(l$setting,l$family,sep=' | ');l$row<-factor(l$row,levels=rev(c(paste('Korea OOF',c('NO','BCCG','BCT'),sep=' | '),paste('US held-out',c('NO','BCCG','BCT'),sep=' | '))))
p<-ggplot(l,aes(metric,row,fill=intensity))+geom_tile(color='white')+geom_text(aes(label=label,color=intensity>.58),size=3.6,show.legend=FALSE)+scale_color_manual(values=c('FALSE'='#172A3A','TRUE'='white'))+scale_fill_gradient(low='#F2F6FA',high='#125384',name='Within-metric\nrelative magnitude')+scale_x_discrete(labels=c('|mean Z|','|SD-1|','|age slope|\nper 10y','|height slope|\nper 10cm','|P10-10%|\npp','|P5-5%|\npp','P10 age\nrange pp','P10 height\nrange pp','P5 height\nrange pp'),position='top')+facet_wrap(~sex,ncol=1)+theme_minimal(base_size=11)+theme(panel.grid=element_blank(),axis.title=element_blank(),plot.caption=element_text(hjust=0))+labs(title='Fixed-structure distribution-family sensitivity',subtitle='Same Korean PSU folds; model-specific US location + scale adaptation only; BCT remains locked primary',caption='Korea: 2014-2019, two repeats of five-fold PSU CV. US: adaptation 2011-2012, held-out 2013-2014.\nAbsolute deviations / ranges; smaller is closer to target. Color scaled separately by metric, not a composite score.\nAll methods use identical age/height basis dimensions; distribution-specific scale parameters have different interpretations.')
